/** Auto-generated — labs markup updated for campus-labs design */
export default "<section class=\"page-hero\">\r\n    <div class=\"container\">\r\n      <div class=\"breadcrumb\"><a href='/'>Home</a> / Courses</div>\r\n      <h1 class=\"page-hero__title\">Courses Offered</h1>\r\n      <p class=\"page-hero__subtitle\">The Right Programs for You</p>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- Pharm-D -->\r\n  <section class=\"section\" id=\"pharmd\">\r\n    <div class=\"container\">\r\n      <div class=\"grid-2 fade-up\">\r\n        <div>\r\n          <span class=\"section__label\">Doctorate Program</span>\r\n          <h2 class=\"section__title\">Pharm-D</h2>\r\n          <p style=\"color: var(--text-light); margin-bottom: 1rem;\"><strong>Duration:</strong> 6 years &nbsp;|&nbsp; <strong>Intake:</strong> 30</p>\r\n          <p style=\"color: var(--text-light);\">The Pharm-D (Doctor of Pharmacy) is a 6-year professional degree program that prepares students for a career as a clinical pharmacist. This program focuses on patient-centered care, drug therapy management, and promoting public health. It is a rigorous program that combines classroom learning with extensive clinical experience. Graduates optimize medication, improving patient outcomes.</p>\r\n          <p style=\"color: var(--primary); font-weight: 600; margin-top: 1rem;\">Full Scholarship Opportunities for SC/ST Students</p>\r\n          <div class=\"course-hospital-tieup\" style=\"margin-top:1.25rem;padding:1rem 1.15rem;border-left:3px solid var(--crimson, #6e1018);background:var(--gold-soft, #f7f1e6);\">\r\n          <p style=\"margin:0 0 0.35rem;font-size:0.75rem;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:var(--crimson-deep, #6e1018);\">Hospital Tie-Up</p>\r\n          <p style=\"margin:0;color:var(--text, #1a1a1a);\"><strong>Government Headquarters Hospital (GH), Tirupattur</strong> — clinical training hospital for Pharm-D students.</p>\r\n          </div>\r\n        </div>\r\n        <div class=\"img-frame fade-up\">\r\n          <img src=\"https://gppharmacycollege.com/wp-content/uploads/2025/03/G.P.Pharmacy-College2.jpg\" alt=\"Pharm-D Program\">\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- B.Pharm -->\r\n  <section class=\"section section--soft\">\r\n    <div class=\"container\">\r\n      <div class=\"grid-2 fade-up\">\r\n        <div>\r\n          <img src=\"https://gppharmacycollege.com/wp-content/uploads/2025/03/G.P.Pharmacy-College4.jpg\" alt=\"B.Pharm Program\" style=\"border-radius: var(--radius-lg); box-shadow: var(--shadow-lg);\">\r\n        </div>\r\n        <div>\r\n          <span class=\"section__label\">Undergraduate Program</span>\r\n          <h2 class=\"section__title\">B.Pharm</h2>\r\n          <p style=\"color: var(--text-light); margin-bottom: 1rem;\"><strong>Duration:</strong> 4 years &nbsp;|&nbsp; <strong>Intake:</strong> 100</p>\r\n          <p style=\"color: var(--text-light);\">Bachelor of Pharmacy (B.Pharm) is an undergraduate degree course in the field of Pharmacy education. Students interested in the medical field (except to become a doctor) can choose this course after the completion of class 12th. After completion, students can practice as a Pharmacist in hospitals, community pharmacies, and industries related to prescription, manufacture & provision of medicines.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- D.Pharm -->\r\n  <section class=\"section\">\r\n    <div class=\"container\">\r\n      <div class=\"grid-2 fade-up\">\r\n        <div>\r\n          <span class=\"section__label\">Diploma Program</span>\r\n          <h2 class=\"section__title\">D.Pharm</h2>\r\n          <p style=\"color: var(--text-light); margin-bottom: 1rem;\"><strong>Duration:</strong> 2 years &nbsp;|&nbsp; <strong>Intake:</strong> 60</p>\r\n          <p style=\"color: var(--text-light);\">D.Pharmacy or D.Pharma is a diploma level course for aspirants who wish to study pharmacy and opt for a career option in medicine. It is a 2-year full-time diploma course designed to prepare candidates to work under the supervision of a licensed pharmacist in hospitals, community pharmacies, and other pharmaceutical-related fields.</p>\r\n        </div>\r\n        <div>\r\n          <img src=\"https://gppharmacycollege.com/wp-content/uploads/2025/03/G.P.Pharmacy-College7.jpg\" alt=\"D.Pharm Program\" style=\"border-radius: var(--radius-lg); box-shadow: var(--shadow-lg);\">\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- M.Pharm -->\r\n  <section class=\"section section--soft\">\r\n    <div class=\"container\">\r\n      <div class=\"grid-2 fade-up\">\r\n        <div>\r\n          <img src=\"https://gppharmacycollege.com/wp-content/uploads/2025/03/Pharmaceutics-lab.jpg\" alt=\"M.Pharm Program\" style=\"border-radius: var(--radius-lg); box-shadow: var(--shadow-lg);\">\r\n        </div>\r\n        <div>\r\n          <span class=\"section__label\">Postgraduate Program</span>\r\n          <h2 class=\"section__title\">M.Pharm</h2>\r\n          <p style=\"color: var(--text-light); margin-bottom: 1rem;\"><strong>Duration:</strong> 2 years</p>\r\n          <ul style=\"color: var(--text-light); margin-bottom: 1rem; padding-left: 1.25rem;\">\r\n            <li>Pharmaceutics — Intake: 15</li>\r\n            <li>Pharmaceutical Analysis — Intake: 15</li>\r\n            <li>Pharmaceutical Regulatory Affairs — Intake: 15</li>\r\n          </ul>\r\n          <p style=\"color: var(--text-light);\">The M.Pharm is a 2-year postgraduate degree program with options in Pharmaceutics (drug formulation and manufacturing), Pharmaceutical Analysis (quality and safety testing), and Regulatory Affairs (drug approval and compliance). These specializations provide advanced training for diverse career paths in the pharmaceutical industry, research, and regulatory agencies.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- B.Pharm Lateral -->\r\n  <section class=\"section\">\r\n    <div class=\"container fade-up\">\r\n      <span class=\"section__label\">Lateral Entry</span>\r\n      <h2 class=\"section__title\">B.Pharm (Direct Second Year)</h2>\r\n      <p style=\"color: var(--text-light); margin-bottom: 1rem;\"><strong>Duration:</strong> 3 years</p>\r\n      <p style=\"color: var(--text-light); max-width: 800px;\">G.P. Pharma College presents a significant opportunity for candidates who have successfully completed their Diploma in Pharmacy examinations. Through the institution's Lateral Entry system, these eligible individuals can directly secure admission into the second year of the Bachelor of Pharmacy (B.Pharm) degree course. This direct entry offers a strategic advantage for those looking to advance their careers efficiently within the pharmaceutical field.</p>\r\n      <div class=\"eligibility-box\" style=\"max-width: 800px;\">\r\n        <h4>Eligibility for All Programs</h4>\r\n        <p><strong>Pass in +2 with any one of the following groups:</strong><br>\r\n        <strong>Group A1:</strong> Physics, Chemistry, Maths and Biology<br>\r\n        <strong>Group A2:</strong> Physics, Chemistry, Maths or Biology &amp; Computer Science<br>\r\n        <strong>Group B:</strong> Physics, Chemistry, Botany and Zoology</p>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n      <!-- Laboratories -->\n  <section class=\"campus-labs section\" id=\"laboratories\">\n    <div class=\"container\">\n      <div class=\"section__header section__header--left fade-up campus-labs__header\">\n        <p class=\"home-section-eyebrow\">Infrastructure</p>\n        <h2 class=\"section__title\">Our Laboratories</h2>\n        <p class=\"section__desc\">Four dedicated labs for manufacturing practice, chemistry, pharmacology, and natural products — where theory becomes skill.</p>\n      </div>\n\n      <div class=\"campus-labs__list\">\n        <article class=\"campus-lab fade-up\" id=\"pharmaceutics\">\n          <figure class=\"campus-lab__media\">\n            <img src=\"https://gppharmacycollege.com/wp-content/uploads/2025/03/Pharmaceutics-lab.jpg\" alt=\"Pharmaceutics Lab\" loading=\"lazy\" width=\"900\" height=\"620\">\n          </figure>\n          <div class=\"campus-lab__body\">\n            <span class=\"campus-lab__index\" aria-hidden=\"true\">01</span>\n            <h3 class=\"campus-lab__title\">Pharmaceutics Lab</h3>\n            <p class=\"campus-lab__text\">This laboratory provides elementary knowledge about the manufacturing of pharmaceutical preparations. This lab is also utilized to teach about the dispensing of drugs in a hospital by a pharmacist and about community pharmacy practice. The lab is used for the preparation of aromatic waters, syrups, liniments, lozenges, lotions, tinctures etc.</p>\n            <ul class=\"campus-lab__focus\"><li>Aromatic waters</li><li>Syrups &amp; liniments</li><li>Lozenges &amp; lotions</li><li>Tinctures</li><li>Dispensing practice</li></ul>\n          </div>\n        </article>\n\n        <article class=\"campus-lab campus-lab--flip fade-up\" id=\"chemistry\">\n          <figure class=\"campus-lab__media\">\n            <img src=\"https://gppharmacycollege.com/wp-content/uploads/2025/03/G.P.Pharmacy-College10.jpg\" alt=\"Pharmaceutical Chemistry Lab\" loading=\"lazy\" width=\"900\" height=\"620\">\n          </figure>\n          <div class=\"campus-lab__body\">\n            <span class=\"campus-lab__index\" aria-hidden=\"true\">02</span>\n            <h3 class=\"campus-lab__title\">Pharmaceutical Chemistry Lab</h3>\n            <p class=\"campus-lab__text\">These well furnished laboratories provide facilities for practical training in pharmaceutical medicinal chemistry, synthesis and structural elucidation of medicinally important compounds. Practical training is also offered in organic chemistry with well designed experiments. Students are familiarized with various organic compounds by their nature, physical and chemical properties and usage in chemical reactions as well as in pharmaceutical industries.</p>\n            <ul class=\"campus-lab__focus\"><li>Medicinal chemistry</li><li>Synthesis</li><li>Structural elucidation</li><li>Organic experiments</li></ul>\n          </div>\n        </article>\n\n        <article class=\"campus-lab fade-up\" id=\"pharmacology\">\n          <figure class=\"campus-lab__media\">\n            <img src=\"https://gppharmacycollege.com/wp-content/uploads/2025/03/G.P.Pharmacy-College12.jpg\" alt=\"Pharmacology Lab\" loading=\"lazy\" width=\"900\" height=\"620\">\n          </figure>\n          <div class=\"campus-lab__body\">\n            <span class=\"campus-lab__index\" aria-hidden=\"true\">03</span>\n            <h3 class=\"campus-lab__title\">Pharmacology Lab</h3>\n            <p class=\"campus-lab__text\">Pharmacology lab consists of equipment to investigate the activity of various drug samples, such as Rota Rod, Electro-convulsiometer, Analgesiometer, Histamine chamber and Actophotometer. Human Anatomy and Physiology of human body is also studied with the help of charts, models including human skeleton and various types of apparatus.</p>\n            <ul class=\"campus-lab__focus\"><li>Rota Rod</li><li>Electro-convulsiometer</li><li>Analgesiometer</li><li>Histamine chamber</li><li>Actophotometer</li></ul>\n          </div>\n        </article>\n\n        <article class=\"campus-lab campus-lab--flip fade-up\" id=\"pharmacognosy\">\n          <figure class=\"campus-lab__media\">\n            <img src=\"https://gppharmacycollege.com/wp-content/uploads/2025/03/G.P.Pharmacy-College17.jpg\" alt=\"Pharmacognosy Lab\" loading=\"lazy\" width=\"900\" height=\"620\">\n          </figure>\n          <div class=\"campus-lab__body\">\n            <span class=\"campus-lab__index\" aria-hidden=\"true\">04</span>\n            <h3 class=\"campus-lab__title\">Pharmacognosy Lab</h3>\n            <p class=\"campus-lab__text\">Pharmacognosy is a specific discipline that deals with the rapid developments in the knowledge and utilization of medicinal substances of biological origin (plant, microorganism and animal products) used for human and veterinary purposes. The laboratory has various instruments like Soxhlet apparatus, Laminar Air Flow, Digital Balance, Calorimeter, UV cabinet.</p>\n            <ul class=\"campus-lab__focus\"><li>Soxhlet apparatus</li><li>Laminar Air Flow</li><li>Digital Balance</li><li>Calorimeter</li><li>UV cabinet</li></ul>\n          </div>\n        </article>\n      </div>\n    </div>\n  </section>"
